// Absender, Betreff und Text aus der Mail holen und die Anfrage an
// Gemini vorbereiten. Der Prompt wurde vorab gegen echte Beispielmails
// getestet (Bug, Feature-Wunsch, Spam, Autoresponder, Werbung).

const mail = $json;

// Die IMAP-Node liefert "from" als Objekt: { value: [{address, name}], text, html }.
// Aeltere Formate liefern einen reinen String - beides wird unterstuetzt.
function absenderAus(feld) {
  if (!feld) return { mail: '', name: '' };
  if (typeof feld === 'string') {
    const treffer = feld.match(/<([^>]+)>/);
    return {
      mail: (treffer ? treffer[1] : feld).trim().toLowerCase(),
      name: feld.replace(/<[^>]*>/, '').replace(/"/g, '').trim()
    };
  }
  const erster = Array.isArray(feld.value) && feld.value[0] ? feld.value[0] : {};
  return {
    mail: String(erster.address || '').trim().toLowerCase(),
    name: String(erster.name || '').trim()
  };
}

const absender = absenderAus(mail.from);
const betreff = String(mail.subject || '').trim();
const text = String(mail.text || mail.textAsHtml || '').trim().slice(0, 6000);

const systemPrompt = [
  'Du bist der Issue-Collector eines Kanban-Boards. Analysiere die E-Mail eines',
  'Stakeholders und extrahiere daraus genau ein Ticket.',
  '',
  'Regeln:',
  '- istEchteAnfrage: true, wenn die Mail ein konkretes Anliegen zum Produkt enthält',
  '  (Fehlermeldung, Feature-Wunsch, technische Aufgabe). false bei Spam, Werbung,',
  '  Autorespondern ("bin im Urlaub"), reinen Grußnachrichten oder Mails ohne',
  '  erkennbares inhaltliches Anliegen (z.B. nur "Bitte um Rückruf").',
  '  Im Zweifel true – lieber ein Ticket zu viel als ein verlorenes Anliegen.',
  '- category: "technical" für technische Aufgaben UND Bug-Meldungen, "user-story"',
  '  für Feature-Wünsche und fachliche Anforderungen.',
  '- title: prägnant, max 60 Zeichen, keine Anrede, kein "Bitte".',
  '- priority: "urgent" bei Wörtern wie dringend, sofort, kritisch, Ausfall,',
  '  Produktion, blockiert. "low" bei irgendwann, Kleinigkeit, nice to have,',
  '  kein Stress. Sonst "medium".',
  '- deadline: Datum aus dem Text streng im ISO-Format JJJJ-MM-TT',
  '  (Beispiel: 2026-09-05). Wenn keins genannt wird: null.',
  '- description: 1-3 Sätze, sachlich zusammengefasst, ohne Grußformeln.',
  '',
  'Schreibe durchgängig korrektes Deutsch MIT Umlauten (ä, ö, ü, ß) – niemals',
  'Umschreibungen wie "ae", "oe", "ue" oder "ss".',
  'Antworte ausschließlich im vorgegebenen JSON-Schema.'
].join('\n');

const schema = {
  type: 'object',
  properties: {
    istEchteAnfrage: { type: 'boolean' },
    category: { type: 'string', enum: ['technical', 'user-story'] },
    title: { type: 'string' },
    priority: { type: 'string', enum: ['urgent', 'medium', 'low'] },
    deadline: { type: 'string', nullable: true },
    description: { type: 'string' }
  },
  required: ['istEchteAnfrage', 'category', 'title', 'priority', 'deadline', 'description']
};

const geminiBody = {
  systemInstruction: { parts: [{ text: systemPrompt }] },
  contents: [{
    role: 'user',
    parts: [{ text: `Von: ${absender.mail}\nBetreff: ${betreff}\n\n${text}` }]
  }],
  generationConfig: {
    responseMimeType: 'application/json',
    responseSchema: schema,
    temperature: 0
  }
};

return {
  json: {
    absenderMail: absender.mail,
    absenderName: absender.name,
    betreff,
    text,
    geminiBody
  }
};

// Gemini-Antwort auswerten und daraus ein Join-Ticket bauen.
// Gibt bewusst NICHTS zurück, wenn die Mail keine echte Anfrage war –
// dann entsteht kein Ticket und das Tageskontingent bleibt unberührt.

const antwort = $json;
const quelle = $('Mail aufbereiten').item.json;

let analyse;
try {
  const rohtext = antwort.candidates[0].content.parts[0].text;
  analyse = JSON.parse(rohtext);
} catch (fehler) {
  throw new Error('Gemini-Antwort nicht lesbar: ' + fehler.message);
}

if (analyse.istEchteAnfrage !== true) {
  return null;
}

// Gemini liefert ISO (JJJJ-MM-TT); Join erwartet TT/MM/JJJJ.
// Umwandlung im Code statt im Prompt, weil das Modell beim Format schwankte.
function alsJoinDatum(iso) {
  if (!iso) return '';
  const teile = String(iso).split('-');
  if (teile.length !== 3) return '';
  const [jahr, monat, tag] = teile;
  return `${tag}/${monat}/${jahr}`;
}

const hinweis = 'Dieses Ticket wurde KI-generiert.';

const ticket = {
  id: Date.now(),
  title: String(analyse.title || quelle.betreff || 'Anfrage ohne Titel').slice(0, 120),
  description: `${String(analyse.description || '').trim()}\n\n${hinweis}`,
  date: alsJoinDatum(analyse.deadline),
  priority: analyse.priority || 'medium',
  category: analyse.category || 'user-story',
  status: 'triage',
  assigned: [],
  subtasks: [],
  creator: {
    email: quelle.absenderMail,
    name: quelle.absenderName || quelle.absenderMail,
    type: 'extern'
  }
};

return { json: { ticket, absenderMail: quelle.absenderMail, betreff: quelle.betreff } };
